t.script:
(function () {
    var subtypeData = JSON.parse(
        document.getElementById('subtype-data').textContent || '{}'
    );
    var savedSubtype = document.getElementById('saved_subtype').value || '';

    var stateSelect = document.getElementById('state');
    var storeSelect = document.getElementById('company_id');
    var equipSelect = document.getElementById('equipment_type');
    var subtypeWrapper = document.getElementById('subtype_wrapper');
    var subtypeSelect = document.getElementById('subtype');

    var allStores = [];
    Array.from(storeSelect.options).forEach(function (opt) {
        if (opt.value) {
            allStores.push({
                value: opt.value,
                text: opt.text,
                state: opt.dataset.state || '',
                selected: opt.selected
            });
        }
    });

    function filterStores(reset) {
        var state = stateSelect.value;
        var prev = storeSelect.value;
        storeSelect.innerHTML = '';
        var ph = document.createElement('option');
        ph.value = '';
        if (!state) {
            ph.textContent = '-- Select a state first --';
            storeSelect.appendChild(ph);
            storeSelect.disabled = true;
            storeSelect.value = '';
            return;
        }
        ph.textContent = '-- Select Store --';
        storeSelect.appendChild(ph);
        storeSelect.disabled = false;
        var matches = [];
        allStores.forEach(function (s) {
            if (s.state === state) {
                var el = document.createElement('option');
                el.value = s.value;
                el.textContent = s.text;
                if (!reset && s.value === prev) el.selected = true;
                storeSelect.appendChild(el);
                matches.push(s);
            }
        });
        if (matches.length === 1) {
            storeSelect.value = matches[0].value;
        } else if (reset) {
            storeSelect.value = '';
        }
    }
    stateSelect.addEventListener('change', function () { filterStores(true); });
    filterStores(false);

    function updateSubtype(reset) {
        var opts = subtypeData[equipSelect.value];
        subtypeSelect.innerHTML = '';
        var ph = document.createElement('option');
        ph.value = '';
        ph.textContent = '-- Select --';
        subtypeSelect.appendChild(ph);
        if (opts) {
            opts.forEach(function (o) {
                var el = document.createElement('option');
                el.value = o[0];
                el.textContent = o[1];
                if (!reset && o[0] === savedSubtype) el.selected = true;
                subtypeSelect.appendChild(el);
            });
            subtypeWrapper.style.display = '';
            subtypeSelect.disabled = false;
            if (opts.length === 1) {
                subtypeSelect.value = opts[0][0];
            }
        } else {
            subtypeWrapper.style.display = 'none';
            subtypeSelect.disabled = true;
            subtypeSelect.value = '';
        }
        if (reset) savedSubtype = '';
    }
    equipSelect.addEventListener('change', function () { updateSubtype(true); });
    updateSubtype(false);
})();

